function safeT(key, localeOverride) {
  const locale = localeOverride || currentLocale || DEFAULT_LOCALE;
  const table = (I18N && I18N[locale]) || {};
  const fallback = (I18N && I18N[DEFAULT_LOCALE]) || {};
  const template = table[key] || fallback[key];
  if (!template) return `TODO_i18n(${key})`;
  return interpolate(template, {});
}

function applyI18n() {
  document.querySelectorAll("[data-i18n]").forEach((el) => {
    const key = el.dataset.i18n;
    if (!key) return;
    const text = t(key, { spell: state.spell });
    if (text) {
      el.textContent = text;
    }
  });

  document.querySelectorAll("[data-i18n-placeholder]").forEach((el) => {
    const key = el.dataset.i18nPlaceholder;
    if (!key) return;
    const text = t(key);
    if (text) {
      el.setAttribute("placeholder", text);
    }
  });

  document.querySelectorAll("[data-i18n-aria]").forEach((el) => {
    const key = el.dataset.i18nAria;
    if (!key) return;
    const text = t(key);
    if (text) {
      el.setAttribute("aria-label", text);
    }
  });

  document.querySelectorAll("[data-i18n-html]").forEach((el) => {
    const key = el.dataset.i18nHtml;
    if (!key) return;
    const text = t(key, { spell: state.spell });
    if (text) {
      el.innerHTML = text;
    }
  });

  document.querySelectorAll(".dock-item").forEach((item) => {
    const labelEl = item.querySelector(".dock-label, .label, .dock-text");
    const label = labelEl ? labelEl.textContent.trim() : "";
    if (label) item.setAttribute("data-label", label);
    if (!item.hasAttribute("tabindex")) item.tabIndex = 0;
  });

  globalThis.renderAboutSubSectionModule?.();
}

// CSSOS_PHASE2_I18N_ENGLISH_AS_SSOT 20260419
//
// English is the SINGLE source of truth. Every other locale — es, fr, ja,
// ko, de, ru, zh, ... — is derived at runtime through the i18n runtime
// (public/i18n/runtime.js, POST /api/i18n/translate). No locale is
// privileged; every locale goes through the exact same code path.
//
// Canonical call: `tr("Change Plan")`. No second argument. If you need to
// interpolate values, pass them as the second `vars` object, which the
// i18n runtime will substitute AFTER translation so tokens are preserved:
//   tr("Hello, {name}!", { name: userName })
//
// On cache miss the function returns the English source verbatim. The
// runtime will resolve the translation asynchronously and dispatch
// `cssos:i18n-translation-ready`; open panels listen for that event and
// re-render so the translated copy replaces the English placeholder.
function tr(english, vars) {
  const source = typeof english === "string" ? english : String(english == null ? "" : english);
  try {
    const i18n = globalThis.CSSOS_I18N;
    if (i18n && typeof i18n.tr === "function") {
      const translated = i18n.tr(source, vars);
      if (typeof translated === "string") return translated;
    }
  } catch (_) { /* fall through */ }
  // Local interpolation fallback when the i18n runtime is unavailable.
  if (vars && typeof vars === "object") {
    return source.replace(/\{(\w+)\}/g, (_m, key) =>
      vars[key] != null ? String(vars[key]) : `{${key}}`
    );
  }
  return source;
}

// DEPRECATED — keep as a thin backward-compat shim for the ~2000 legacy
// call sites that still pass (en, zh). The second argument is IGNORED —
// we no longer privilege Chinese. Use `tr(english)` in new code.
function loginCopy(en, _zhIgnoredLegacy) {
  return tr(en);
}

function emergencyUnfreezeUi(options = {}) {
  const preserveHoldState = !!options?.preserveHoldState;
  document.body.classList.remove("longpress-guard");
  if (!preserveHoldState) {
    document.body.classList.remove("holding-mic");
  }
  dismissUiBlockingLayers();
}

function callWatchUiModule(name, ...args) {
  const fn = globalThis[name];
  if (typeof fn !== "function") return undefined;
  return fn(...args);
}

function readWatchUiModule(name, fallback, ...args) {
  const value = callWatchUiModule(name, ...args);
  return value === undefined ? fallback : value;
}

function callCreationFlowModule(name, ...args) {
  const fn = globalThis[name];
  if (typeof fn !== "function") return undefined;
  return fn(...args);
}

function readCreationFlowModule(name, fallback, ...args) {
  const value = callCreationFlowModule(name, ...args);
  return value === undefined ? fallback : value;
}

function openWatchPreviewFlow(options = {}) {
  return readWatchUiModule("openWatchPreviewFlowModule", Promise.resolve(false), options);
}

function openWatchMusicPlaybackSurface(options = {}) {
  return readWatchUiModule("openWatchMusicPlaybackSurfaceModule", false, options);
}

function renderSongSeedPreview(seed = state.songSeed) {
  callWatchUiModule("renderSongSeedPreviewModule", seed);
}

function syncWatchEditorsFromSettings() {
  callWatchUiModule("syncWatchEditorsFromSettingsModule");
}

function initWatchVideoPlaybackControls() {
  callWatchUiModule("initWatchVideoPlaybackControlsModule");
}

function initWatchMusicControls() {
  callWatchUiModule("initWatchMusicControlsModule");
}

function setSelectValueSafe(selectEl, value) {
  if (!selectEl || !value) return;
  const opts = Array.from(selectEl.options || []);
  const found = opts.find((o) => o.value === value || o.text === value);
  if (found) {
    selectEl.value = found.value;
    return;
  }
  const opt = document.createElement("option");
  opt.value = value;
  opt.textContent = value;
  selectEl.appendChild(opt);
  selectEl.value = value;
}

function hashSeedString(input) {
  const text = String(input || "");
  let hash = 2166136261;
  for (let i = 0; i < text.length; i += 1) {
    hash ^= text.charCodeAt(i);
    hash = Math.imul(hash, 16777619);
  }
  return hash >>> 0;
}

function seededUnit(seed, offset = 0) {
  const value = Math.sin((seed + 1 + offset) * 12.9898) * 43758.5453;
  return value - Math.floor(value);
}

function seededPick(list, seed, offset = 0) {
  const items = Array.isArray(list) ? list : [];
  if (!items.length) return "";
  const index = Math.floor(seededUnit(seed, offset) * items.length) % items.length;
  return items[index];
}

function seededNumber(min, max, step, seed, offset = 0) {
  const safeMin = Number(min || 0);
  const safeMax = Number(max || safeMin);
  const safeStep = Math.max(1, Number(step || 1));
  const count = Math.max(1, Math.floor((safeMax - safeMin) / safeStep) + 1);
  return safeMin + (Math.floor(seededUnit(seed, offset) * count) % count) * safeStep;
}

function syncCreationStateToLegacyInputs() {
  // CSSMV_DEFAULTS_EMPTY 20260420 — Jing: do NOT pre-fill Advanced Settings
  // with "Chinese GuFeng" / "Feminine" — those were polluting the panel and
  // forcing every generation into a Chinese-GuFeng feminine voice regardless
  // of UI language. Empty inputs let the LLM / UI-language driver decide.
  const genre = creationState.selections.genre || "";
  const mood = creationState.selections.mood;
  const instrument = creationState.selections.instrument;
  const instrumentation = creationState.instrumentation || "";
  const ensembleStyle = creationState.ensembleStyle || "";
  const styleText = [genre, mood, instrument, instrumentation, ensembleStyle].filter(Boolean).join(" · ");
  setSelectValueSafe(styleInput, styleText || genre);
  setSelectValueSafe(voiceInput, creationState.selections.vocalGender || "");
}

function normalizeWorkTypeClient(value) {
  const raw = String(value || "").trim().toLowerCase();
  if (raw === "triptych") return "triptych";
  if (raw === "opera") return "opera";
  return "single";
}

function inferStructuredWorkType(title, fallback = "single") {
  return normalizeWorkTypeClient(fallback);
}

function inferLanguageFromTitleText(value) {
  const text = String(value || "").trim();
  if (!text) return "";
  const han = (text.match(/[\u4E00-\u9FFF]/g) || []).length;
  const hiraKata = (text.match(/[\u3040-\u30FF]/g) || []).length;
  const latin = (text.match(/[A-Za-z]/g) || []).length;
  if (hiraKata >= Math.max(2, han, latin)) return "ja";
  if (han >= Math.max(2, hiraKata, latin)) return "zh";
  if (latin >= Math.max(2, han + hiraKata)) return "en";
  return "";
}

function workTypeLabel(workType) {
  const normalized = normalizeWorkTypeClient(workType);
  if (normalized === "triptych") return loginCopy("Triptych");
  if (normalized === "opera") return loginCopy("Opera");
  return loginCopy("Single");
}

function workStructureRoleLabel(role, fallbackType) {
  const raw = String(role || "").trim().toLowerCase();
  if (raw === "act") return loginCopy("Act");
  if (raw === "scene") return loginCopy("Scene");
  if (raw === "triptych") return loginCopy("Triptych");
  if (raw === "opera") return loginCopy("Opera");
  return workTypeLabel(fallbackType);
}

function workOwnerChainLabel(chain) {
  const items = Array.isArray(chain) ? chain : [];
  const labels = items
    .map((entry) => String(entry?.label || "").trim())
    .filter(Boolean);
  if (!labels.length) return "";
  return `${loginCopy("Ownership")} · ${labels.join(" → ")}`;
}

function flattenHierarchyWorks(items) {
  const list = Array.isArray(items) ? items : [];
  const flat = [];
  const walk = (node) => {
    if (!node || typeof node !== "object") return;
    flat.push(node);
    const children = Array.isArray(node.children) ? node.children : [];
    children.forEach(walk);
  };
  list.forEach(walk);
  return flat;
}

function sortHierarchyNodes(nodes) {
  return [...(Array.isArray(nodes) ? nodes : [])].sort((a, b) => {
    const seqDelta = Number(a?.sequence_index || 0) - Number(b?.sequence_index || 0);
    if (seqDelta !== 0) return seqDelta;
    const timeDelta = workCreatedTimestamp(b) - workCreatedTimestamp(a);
    if (timeDelta !== 0) return timeDelta;
    return String(a?.title || "").localeCompare(String(b?.title || ""));
  });
}

function buildWorkHierarchy(items) {
  const list = Array.isArray(items) ? items : [];
  if (!list.length) return [];
  const nodesById = new Map();
  list.forEach((item) => {
    const id = String(item?.work_id || item?.id || item?.local_id || "").trim();
    if (!id) return;
    const existing = nodesById.get(id) || {};
    nodesById.set(id, {
      ...existing,
      ...item,
      children: [...(Array.isArray(existing.children) ? existing.children : []), ...(Array.isArray(item?.children) ? item.children : [])]
    });
  });
  nodesById.forEach((node) => {
    node.children = buildWorkHierarchy(node.children || []);
  });
  const roots = [];
  nodesById.forEach((node) => {
    const parentId = String(node?.parent_work_id || "").trim();
    if (!parentId || !nodesById.has(parentId)) {
      roots.push(node);
      return;
    }
    const parent = nodesById.get(parentId);
    parent.children = Array.isArray(parent.children) ? parent.children : [];
    const nodeId = String(node?.work_id || node?.id || node?.local_id || "").trim();
    if (!parent.children.some((child) => String(child?.work_id || child?.id || child?.local_id || "").trim() === nodeId)) {
      parent.children.push(node);
    }
  });
  const walk = (nodes) =>
    sortHierarchyNodes(nodes).map((node) => ({
      ...node,
      children: walk(node.children || [])
    }));
  return walk(roots);
}

function filterDisplayWorkRoots(nodes) {
  const roots = Array.isArray(nodes) ? nodes : [];
  const allIds = new Set(flattenHierarchyWorks(roots).map((node) => String(node?.work_id || node?.id || node?.local_id || "").trim()).filter(Boolean));
  return roots.filter((node) => {
    const nodeId = String(node?.work_id || node?.id || node?.local_id || "").trim();
    const rootId = String(node?.root_work_id || "").trim();
    const parentId = String(node?.parent_work_id || "").trim();
    if (parentId) return false;
    if (rootId && rootId !== nodeId && allIds.has(rootId)) return false;
    return true;
  });
}

function renderHierarchyTree(nodes, context = "market") {
  const items = Array.isArray(nodes) ? nodes : [];
  if (!items.length) return "";
  return `
    <div class="work-hierarchy">
      ${items
        .map((node, index) => {
          const title = escapeHtml(String(node?.title || "").trim() || loginCopy("Untitled"));
          const role = escapeHtml(workStructureRoleLabel(node?.structure_role, node?.work_type));
          const nodeRole = String(node?.structure_role || "").trim().toLowerCase();
          const summary = escapeHtml(
            context === "works" && ["opera", "triptych", "act"].includes(nodeRole)
              ? ""
              : String(node?.style || node?.lyrics_preview || "").trim()
          );
          const createdAt = formatDateTime(node?.created_at);
          const children = renderHierarchyTree(node?.children || [], context);
          const workId = escapeHtml(String(node?.id || "").trim());
          const isOwnedByViewer =
            Boolean(authState.user?.id) && String(node?.owner_user_id || "").trim() === String(authState.user?.id || "").trim();
          const canTransact = !!authState.user && !isOwnedByViewer;
          const listenCents = Number(node?.current_listen_price_cents || 0);
          const buyoutCents = Number(node?.current_buyout_price_cents || 0);
          const buyoutEnabled = Boolean(node?.buyout_enabled) && buyoutCents > 0;
          const tipsEnabled = canReceiveTips(node);
          const orderState = resolveViewerOrderState(node?.viewer_orders);
          const listenDisabled = Boolean(
            isOwnedByViewer || orderState.paidBuyout || orderState.paidListen || orderState.pendingListen || orderState.pendingBuyout
          );
          const buyoutDisabled = Boolean(isOwnedByViewer || orderState.paidBuyout || orderState.pendingBuyout);
          const tipDisabled = Boolean(!tipsEnabled || orderState.pendingTip);
          const actions =
            context === "market" && workId
              ? `
                <div class="work-hierarchy-actions">
                  <button class="mini-btn ghost tiny" type="button" data-market-action="preview" data-market-child-id="${workId}">${loginCopy("Preview")}</button>
                  ${canTransact ? `<button class="mini-btn ghost tiny" type="button" data-market-action="listen" data-market-child-id="${workId}" ${(listenCents > 0 && !listenDisabled) ? "" : "disabled"}>${marketActionCopy("listen", orderState)}</button>` : ""}
                  ${canTransact ? `<button class="mini-btn market-buyout-btn tiny" type="button" data-market-action="buyout" data-market-child-id="${workId}" ${(!buyoutEnabled || buyoutDisabled) ? "disabled" : ""}>${marketActionCopy("buyout", orderState)}</button>` : ""}
                  ${canTransact ? `<span class="market-inline-action"><button class="mini-btn ghost tiny" type="button" data-market-action="tip" data-market-child-id="${workId}" ${tipDisabled ? "disabled" : ""}>${marketActionCopy("tip", orderState)}</button><input class="inline-chip-input market-tip-input" type="number" min="1" step="1" inputmode="decimal" placeholder="${escapeHtml(loginCopy("Tip $"))}" data-market-tip-input="${workId}" hidden /></span>` : ""}
                </div>
              `
              : context === "works" && workId
              ? `
                <div class="work-hierarchy-actions">
                  <button class="mini-btn ghost tiny" type="button" data-work-action="watch" data-work-child-id="${workId}" ${hasPanelPermission("works.watch") ? "" : "disabled"}>${loginCopy("Enjoy")}</button>
                </div>
              `
              : "";
          return `
            <details class="work-hierarchy-item" ${index === 0 ? "open" : ""}>
              <summary data-foryou-summary data-node-key="${escapeHtml(String(node?.foryou_key || ""))}" data-structure-role="${escapeHtml(String(node?.structure_role || ""))}" data-has-children="${Array.isArray(node?.children) && node.children.length ? "1" : "0"}">
                <span class="work-hierarchy-role">${role}</span>
                <span class="work-hierarchy-title">${title}</span>
                ${createdAt ? `<span class="work-hierarchy-time">${escapeHtml(createdAt)}</span>` : ""}
              </summary>
              ${summary ? `<div class="work-hierarchy-summary">${summary}</div>` : ""}
              ${actions}
              ${children}
            </details>
          `;
        })
        .join("")}
    </div>
  `;
}

function workTypePricingDefaults(workType) {
  const stored = panelDefaultsState.creation?.pricing_by_type?.[normalizeWorkTypeClient(workType)] || null;
  if (stored) {
    return {
      listenCents: Number(stored.listen_cents || 99),
      buyoutCents: Number(stored.buyout_cents || 299)
    };
  }
  const normalized = normalizeWorkTypeClient(workType);
  if (normalized === "triptych") return { listenCents: 99, buyoutCents: 499 };
  if (normalized === "opera") return { listenCents: 99, buyoutCents: 999 };
  return { listenCents: 99, buyoutCents: 299 };
}

function buildCurrentCreationDefaultsPayload() {
  const workType = normalizeWorkTypeClient(creationState.workType);
  const pricingByType = panelDefaultsState.creation?.pricing_by_type
    ? JSON.parse(JSON.stringify(panelDefaultsState.creation.pricing_by_type))
    : {
        single: { listen_cents: 99, buyout_cents: 299 },
        triptych: { listen_cents: 99, buyout_cents: 499 },
        opera: { listen_cents: 99, buyout_cents: 999 }
      };
  const listenCents = centsFromPriceInput(creationDefaultListen?.value || "");
  const buyoutCents = centsFromPriceInput(creationDefaultBuyout?.value || "");
  pricingByType[workType] = {
    listen_cents: listenCents > 0 ? listenCents : workTypePricingDefaults(workType).listenCents,
    buyout_cents: buyoutCents >= 0 ? buyoutCents : workTypePricingDefaults(workType).buyoutCents
  };
  return {
    creative: {
      genre: creationState.selections.genre || "",
      mood: creationState.selections.mood || "",
      instrument: creationState.selections.instrument || "",
      instrumentation: creationState.instrumentation || "",
      ambience: creationState.selections.ambience || "",
      vocal_gender: creationState.selections.vocalGender || "",
      vocal_style: creationState.vocalStyle || "",
      ensemble_style: creationState.ensembleStyle || "",
      arrangement_density: Number(creationState.arrangementDensity || 0.6),
      dynamics_curve: creationState.dynamicsCurve || "",
      section_form: creationState.sectionForm || "",
      articulation_bias: creationState.articulationBias || "",
      voicing_register: creationState.voicingRegister || "",
      percussion_activity: Number(creationState.percussionActivity || 0.45),
      expression_cc_bias: creationState.expressionCcBias || "",
      humanization: Number(creationState.humanization || 0.35),
      inspiration_notes: String(creationState.inspirationNotes || "").slice(0, 1000),
      licensed_style_pack: creationState.licensedStylePack || "",
      external_audio_adapter: creationState.externalAudioAdapter || "",
      tempo_bpm: Number(creationState.tempo || 88),
      musical_key: creationState.key || "C",
      duration_s: Number(creationState.duration || 180),
      language: creationState.language || globalThis.resolveUiPrimaryLanguageModule?.() || globalThis.resolveUiDefaultCreationLanguageModule?.() || "en",
      prompt: String(creationState.prompt || "").slice(0, 500),
      work_type: workType
    },
    pricing_by_type: pricingByType
  };
}

function applyCreationDefaults(template) {
  if (!template || typeof template !== "object") return;
  panelDefaultsState.creation = template;
  resetCreationTouchedFields();
  const creative = template.creative || {};
  // CSSMV_DEFAULTS_EMPTY 20260420 — Jing: applyCreationDefaults was the OTHER
  // entry point forcing "Chinese GuFeng" / "Feminine". When the server defaults
  // template is absent or fields are blank, we now leave them empty so the UI
  // language (English / Japanese / Chinese) drives random output, not a stale
  // Chinese-GuFeng preset from day-zero config.
  creationState.selections = {
    genre: String(creative.genre || ""),
    mood: String(creative.mood || ""),
    instrument: String(creative.instrument || ""),
    ambience: String(creative.ambience || ""),
    vocalGender: String(creative.vocal_gender || "")
  };
  creationState.instrumentation = String(creative.instrumentation || "");
  creationState.vocalStyle = String(creative.vocal_style || "");
  creationState.ensembleStyle = String(creative.ensemble_style || "");
  creationState.arrangementDensity = Math.max(0.2, Math.min(1, Number(creative.arrangement_density || 0.6)));
  creationState.dynamicsCurve = String(creative.dynamics_curve || "");
  creationState.sectionForm = String(creative.section_form || "");
  creationState.articulationBias = String(creative.articulation_bias || "");
  creationState.voicingRegister = String(creative.voicing_register || "");
  creationState.percussionActivity = Math.max(0, Math.min(1, Number(creative.percussion_activity || 0.45)));
  creationState.expressionCcBias = String(creative.expression_cc_bias || "");
  creationState.humanization = Math.max(0, Math.min(1, Number(creative.humanization || 0.35)));
  creationState.inspirationNotes = String(creative.inspiration_notes || "").slice(0, 1000);
  creationState.licensedStylePack = String(creative.licensed_style_pack || "");
  creationState.externalAudioAdapter = String(creative.external_audio_adapter || "");
  // CSSOS_PHASE2_NO_HARDCODED_DEFAULTS 20260427 #162 — Jing
  // "不要写死默认 88 / C / 180 / single — 都从歌词引擎根据 UI 文明派生。"
  creationState.tempo = creative.tempo_bpm ? Number(creative.tempo_bpm) : null;
  creationState.key = String(creative.musical_key || "");
  creationState.duration = creative.duration_s ? Number(creative.duration_s) : null;
  creationState.language = String(creative.language || globalThis.resolveUiPrimaryLanguageModule?.() || globalThis.resolveUiDefaultCreationLanguageModule?.() || "en");
  creationState.workType = String(creative.work_type || "").trim()
    ? normalizeWorkTypeClient(creative.work_type)
    : "";
  creationState.prompt = String(creative.prompt || "").slice(0, 500);
  syncCreationStateToLegacyInputs();
  const pricing = workTypePricingDefaults(creationState.workType);
  if (creationDefaultListen) creationDefaultListen.value = (pricing.listenCents / 100).toFixed(2);
  if (creationDefaultBuyout) creationDefaultBuyout.value = (pricing.buyoutCents / 100).toFixed(2);
  renderCreationConsole();
}

async function loadCreationPanelDefaults(force = false) {
  if (panelDefaultsState.loading) return panelDefaultsState.creation;
  if (!force && panelDefaultsState.loaded && panelDefaultsState.creation) return panelDefaultsState.creation;
  panelDefaultsState.loading = true;
  try {
    const res = await fetch("/api/panel-defaults/creation", { credentials: "include" });
    const payload = await res.json().catch(() => null);
    const data = getApiData(payload);
    const defaults = data?.defaults || null;
    if (res.ok && defaults) {
      panelDefaultsState.loaded = true;
      applyCreationDefaults(defaults);
      return defaults;
    }
  } catch (_err) {
    // ignore
  } finally {
    panelDefaultsState.loading = false;
  }
  return panelDefaultsState.creation;
}

async function saveCreationPanelDefaults(trigger) {
  if (getUserRole() !== "admin") return;
  try {
    setButtonBusy(trigger, true);
    const res = await fetch("/api/panel-defaults/creation", {
      method: "PATCH",
      headers: { "Content-Type": "application/json" },
      credentials: "include",
      body: JSON.stringify({ defaults: buildCurrentCreationDefaultsPayload() })
    });
    const payload = await res.json().catch(() => null);
    const data = getApiData(payload);
    if (!res.ok || payload?.ok === false || !data?.defaults) {
      throw new Error(payload?.code || `defaults_save_failed:${res.status}`);
    }
    applyCreationDefaults(data.defaults);
    showToast(loginCopy("Default template saved."));
  } catch (_err) {
    showToast(loginCopy("Failed to save defaults."));
  } finally {
    setButtonBusy(trigger, false);
  }
}

function creationSummaryText() {
  const s = creationState.selections;
  const styleSummary = String(styleInput?.value || "").trim();
  // CSSOS_PHASE2_GET_MEMBERSHIP_PRESET_GUARD 20260426 #136 — Jing
  // Same defensive guard as in app.creation-duration.js. Load order
  // race with app.api-billing.js can leave getMembershipPreset
  // undefined at the moment creationSummaryText runs.
  const _gmp = (typeof globalThis.getMembershipPreset === "function")
    ? globalThis.getMembershipPreset
    : (typeof getMembershipPreset === "function" ? getMembershipPreset : null);
  const preset = _gmp ? _gmp() : { tier: "guest", monthlyGenerationLimit: 0, maxDurationSec: 60, maxResolution: "720p", watermark: "default", queuePriority: "standard" };
  // CSSOS_PHASE2_DESCRIBE_MEMBERSHIP_GUARD 20260426 #143 — Jing
  // Same load-order race as getMembershipPreset.
  const _dmt = (typeof globalThis.describeMembershipTier === "function")
    ? globalThis.describeMembershipTier
    : (typeof describeMembershipTier === "function" ? describeMembershipTier : null);
  const _safeTierLabel = _dmt ? _dmt(preset.tier) : String(preset.tier || "guest");
  const membershipSummary = [
    `${loginCopy("Tier")}: ${_safeTierLabel}`,
    preset.monthlyGenerationLimit === null
      ? loginCopy("Monthly Limit: Unlimited")
      : loginCopy(`Monthly Limit: ${preset.monthlyGenerationLimit}`),
    `${loginCopy("Max Video")}: ${preset.maxDurationSec}s / ${preset.maxResolution}`,
    `${loginCopy("Watermark")}: ${
      preset.watermark === "none"
        ? loginCopy("Off")
        : preset.watermark === "custom_or_none"
          ? loginCopy("Custom or off")
          : loginCopy("Default")
    }`
  ];
  const parts = [
    ...membershipSummary,
    styleSummary && `${t("settings.musicStyle")}: ${styleSummary}`,
    s.genre && `${creationTabLabel("genre")}: ${creationChipLabel("genre", s.genre)}`,
    s.mood && `${creationTabLabel("mood")}: ${creationChipLabel("mood", s.mood)}`,
    s.instrument && `${creationTabLabel("instrument")}: ${creationChipLabel("instrument", s.instrument)}`,
    s.ambience && `${creationTabLabel("ambience")}: ${creationChipLabel("ambience", s.ambience)}`,
    s.vocalGender && `${creationTabLabel("vocalGender")}: ${creationChipLabel("vocalGender", s.vocalGender)}`,
    creationState.instrumentation && `${loginCopy("Instrumentation")}: ${creationState.instrumentation}`,
    creationState.vocalStyle && `${loginCopy("Vocal Style")}: ${creationState.vocalStyle}`,
    creationState.ensembleStyle && `${loginCopy("Ensemble")}: ${creationState.ensembleStyle}`,
    creationState.licensedStylePack && `${loginCopy("Licensed Pack")}: ${creationState.licensedStylePack}`,
    creationState.externalAudioAdapter && `${loginCopy("Audio Adapter")}: ${creationState.externalAudioAdapter}`,
    creationState.voicingRegister && `${loginCopy("Register")}: ${creationState.voicingRegister}`,
    creationState.expressionCcBias && `${loginCopy("Expression")}: ${creationState.expressionCcBias}`,
    `${loginCopy("Percussion")}: ${Math.round(Number(creationState.percussionActivity || 0) * 100)}%`,
    `${loginCopy("Humanization")}: ${Math.round(Number(creationState.humanization || 0) * 100)}%`,
    `${loginCopy("Work Type")}: ${workTypeLabel(creationState.workType)}`,
    `${t("settings.tempoBpm")}: ${creationState.tempo} BPM`,
    `${t("settings.key")}: ${creationState.key}`,
    `${t("settings.durationSec")}: ${creationState.duration}s`,
    `${t("settings.language")}: ${creationState.language}`
  ].filter(Boolean);
  return parts.join(" | ");
}

