async function requestForyouThumbnail(title, subtitle, lines = []) {
  try {
    const image = await requestThumbnailDataUrl(title, subtitle, lines);
    if (!image) return false;
    if (getForyouPreviewMode() !== FORYOU_PREVIEW_MODES.VIDEO) {
      setForyouThumbImage(image);
      syncWatchPlaceholderAfterForyouThumbModule();
    }
    return true;
  } catch (_err) {
    return false;
  }
}

async function requestThumbnailDataUrl(title, subtitle, lines = []) {
  const cacheKey = JSON.stringify([title || "", subtitle || "", Array.isArray(lines) ? lines.slice(0, 8) : []]);
  if (workThumbCache.has(cacheKey)) return workThumbCache.get(cacheKey);
  try {
    const res = await fetch("/api/cssmv/thumbnail", {
      method: "POST",
      headers: { "content-type": "application/json" },
      body: JSON.stringify({
        title,
        subtitle,
        lyrics: Array.isArray(lines) ? lines.slice(0, 8) : [],
        output_format: FORYOU_THUMB_OUTPUT_FORMAT,
        output_compression: FORYOU_THUMB_OUTPUT_COMPRESSION,
        background: FORYOU_THUMB_BACKGROUND
      })
    });
    if (!res.ok) return "";
    const raw = await res.json();
    const data = getApiData(raw);
    const image = data?.image_data_url || data?.image_url || "";
    if (image) {
      workThumbCache.set(cacheKey, image);
    }
    return image || "";
  } catch (_err) {
    return "";
  }
}

