function restoreMusicDeliveryRewriteBundle(bundle) {
  if (!bundle || typeof bundle !== "object") return;
  const selectedSection =
    findMusicDeliverySection(bundle?.section?.id) || currentMusicDeliverySections()[0] || null;
  deliveryDashboardState.rewritePatchBundle = bundle;
  deliveryDashboardState.restoredRewriteBundleId = String(bundle.bundle_id || "");
  deliveryDashboardState.rewritePatchBundleVersionName = String(bundle.version_name || "");
  applyMusicDeliveryRewriteSandbox({
    arrangementData: deliveryDashboardState.arrangementData,
    mode: String(bundle.mode || "mutation"),
    providerPayload: bundle.provider_payload || {},
    cuePatchPlan: bundle.cue_patch_plan || {},
    selectedSection
  });
  deliveryDashboardState.rewriteMixLane = "rewritten";
}

async function saveMusicDeliveryRewriteBundle(bundle) {
  const runId = String(deliveryDashboardState.runId || "").trim();
  if (!runId || !bundle) return null;
  deliveryDashboardState.rewritePatchBundleSaving = true;
  deliveryDashboardState.rewritePatchBundleError = "";
  renderMusicDeliveryDashboard();
  try {
    const res = await fetch(
      `${apiBase()}/cssapi/v1/runs/${encodeURIComponent(runId)}/music-rewrite-bundles`,
      {
        method: "POST",
        headers: {
          accept: "application/json",
          "content-type": "application/json"
        },
        body: JSON.stringify({
          bundle,
          version_name: String(deliveryDashboardState.rewritePatchBundleVersionName || "").trim() || undefined
        })
      }
    );
    if (!res.ok) {
      throw new Error(`rewrite bundle save failed: ${res.status}`);
    }
    const payload = await res.json();
    deliveryDashboardState.rewritePatchBundle = payload?.entry?.bundle || bundle;
    deliveryDashboardState.restoredRewriteBundleId = String(payload?.entry?.bundle_id || "");
    deliveryDashboardState.rewritePatchBundleVersionName = String(payload?.entry?.version_name || "");
    await loadMusicDeliveryDashboard(runId, true);
    return payload;
  } catch (error) {
    deliveryDashboardState.rewritePatchBundleError = String(error);
    renderMusicDeliveryDashboard();
    return null;
  } finally {
    deliveryDashboardState.rewritePatchBundleSaving = false;
    renderMusicDeliveryDashboard();
  }
}

