async function runMusicComplianceAction(action, options = {}) {
  const runId = String(deliveryDashboardState.runId || "").trim();
  if (!runId || !action) return null;
  deliveryDashboardState.error = "";
  renderMusicDeliveryDashboard();
  try {
    const res = await fetch(
      `${apiBase()}/cssapi/v1/runs/${encodeURIComponent(runId)}/music-compliance-actions`,
      {
        method: "POST",
        headers: {
          accept: "application/json",
          "content-type": "application/json"
        },
        body: JSON.stringify({
          action,
          candidate_id: options.candidateId || undefined,
          target_path: options.targetPath || undefined,
          target_team: options.targetTeam || undefined,
          note: options.note || undefined,
          active_kid: options.activeKid || undefined,
          secret_keyset: options.secretKeyset || undefined,
          vendor: options.vendor || undefined,
          required_fields: options.requiredFields || undefined,
          optional_fields: options.optionalFields || undefined,
          field_defaults: options.fieldDefaults || undefined,
          reopen_reason: options.reopenReason || undefined,
          preset_name: options.presetName || undefined,
          scoped_permissions: options.scopedPermissions || undefined,
          actor_id:
            options.actorId || String(deliveryDashboardState.complianceActorId || "").trim() || undefined,
          actor_name:
            options.actorName || String(deliveryDashboardState.complianceActorName || "").trim() || undefined,
          actor_role:
            options.actorRole || String(deliveryDashboardState.complianceActorRole || "").trim() || undefined,
          actor_directory: options.actorDirectory || undefined,
          role_policy_name: options.rolePolicyName || undefined,
          approval_decision: options.approvalDecision || undefined,
          approver_routing: options.approverRouting || undefined,
          required_signers: options.requiredSigners || undefined,
          quorum_name: options.quorumName || undefined
        })
      }
    );
    if (!res.ok) {
      const detail = await res.text().catch(() => "");
      throw new Error(`compliance action ${action} failed: ${res.status}${detail ? ` ${detail}` : ""}`);
    }
    const payload = await res.json();
    await loadMusicDeliveryDashboard(runId, true);
    return payload;
  } catch (error) {
    deliveryDashboardState.error = String(error);
    renderMusicDeliveryDashboard();
    return null;
  }
}

async function runPublishRunbookAutomation(context = {}) {
  const {
    publishCandidateId,
    currentActor,
    suggestedActor,
    missingSignerRoles,
    readinessChecklist,
    approvalToPublishTrace
  } = context;
  deliveryDashboardState.publishRunbookStatus = dashboardCopy(
    "Running guided publish runbook...",
    "正在执行引导式发布 runbook..."
  );
  renderMusicDeliveryDashboard();
  try {
    const actorForApproval =
      suggestedActor && missingSignerRoles.includes(String(suggestedActor?.actor_role || "").toLowerCase())
        ? suggestedActor
        : currentActor;
    const actorRole = String(actorForApproval?.actor_role || "").trim().toLowerCase();
    if (missingSignerRoles.includes(actorRole)) {
      const approved = await runMusicComplianceAction("approve_compliance_action", {
        candidateId: publishCandidateId || undefined,
        actorId: actorForApproval?.actor_id || undefined,
        actorName: actorForApproval?.actor_name || undefined,
        actorRole: actorForApproval?.actor_role || undefined,
        approvalDecision: "approved",
        note: "Approval recorded from guided publish runbook"
      });
      if (!approved) {
        deliveryDashboardState.publishRunbookStatus = dashboardCopy(
          "Runbook paused because the approval step did not complete.",
          "runbook 已暂停，因为签发步骤没有完成。"
        );
        renderMusicDeliveryDashboard();
        return null;
      }
    }
    const requiredSigners = Array.isArray(approvalToPublishTrace?.required_signers)
      ? approvalToPublishTrace.required_signers
      : [];
    const quorumReady = readinessChecklist.find((item) => item.id === "quorum")?.ready;
    if (!quorumReady) {
      const finalized = await runMusicComplianceAction("finalize_release_quorum", {
        candidateId: publishCandidateId || undefined,
        actorId: actorForApproval?.actor_id || undefined,
        actorName: actorForApproval?.actor_name || undefined,
        actorRole: actorForApproval?.actor_role || undefined,
        quorumName: String(deliveryDashboardState.complianceQuorumName || "").trim() || "final-release-gate",
        requiredSigners: requiredSigners.length ? requiredSigners : undefined,
        note: "Release quorum checked from guided publish runbook"
      });
      if (!finalized) {
        deliveryDashboardState.publishRunbookStatus = dashboardCopy(
          "Runbook paused because the final gate step did not complete.",
          "runbook 已暂停，因为最终门禁步骤没有完成。"
        );
        renderMusicDeliveryDashboard();
        return null;
      }
    }
    deliveryDashboardState.publishRunbookStatus = dashboardCopy(
      "Guided publish runbook finished. Review the refreshed checklist before you publish.",
      "引导式发布 runbook 已完成。发布前请再确认刷新后的清单。"
    );
    renderMusicDeliveryDashboard();
    return true;
  } catch (_error) {
    deliveryDashboardState.publishRunbookStatus = dashboardCopy(
      "Guided publish runbook stopped because one of the recovery steps failed.",
      "引导式发布 runbook 已停止，因为其中一个补救步骤失败了。"
    );
    renderMusicDeliveryDashboard();
    return null;
  }
}

async function playMusicDeliveryRoleFocus(role, sectionId = deliveryDashboardState.selectedSection) {
  applyMusicDeliveryRoleFocus(role);
  if (sectionId) {
    await playMusicDeliverySection(sectionId, false);
    return;
  }
  await startMusicDeliveryMixerPlayback();
}

async function playMusicDeliveryPhrase(phraseId, sectionId = deliveryDashboardState.selectedSection) {
  const phrase = applyMusicDeliveryPhraseFocus(phraseId, sectionId);
  if (!phrase) return;
  await startMusicDeliveryMixerPlayback({
    startSec: phrase.startSec,
    durationSec: Math.max(0.15, phrase.endSec - phrase.startSec),
    label: phrase.id,
    loop: false
  });
}

async function playMusicDeliveryChordSlot(chordSlot, sectionId = deliveryDashboardState.selectedSection) {
  const phrases = applyMusicDeliveryChordSlotFocus(chordSlot, sectionId);
  if (!phrases.length) return;
  const startSec = Math.min(...phrases.map((phrase) => phrase.startSec));
  const endSec = Math.max(...phrases.map((phrase) => phrase.endSec));
  await startMusicDeliveryMixerPlayback({
    startSec,
    durationSec: Math.max(0.15, endSec - startSec),
    label: chordSlot,
    loop: false
  });
}

async function playMusicDeliveryArticulation(articulation, sectionId = deliveryDashboardState.selectedSection) {
  const phrases = applyMusicDeliveryArticulationFocus(articulation, sectionId);
  if (!phrases.length) return;
  const startSec = Math.min(...phrases.map((phrase) => phrase.startSec));
  const endSec = Math.max(...phrases.map((phrase) => phrase.endSec));
  await startMusicDeliveryMixerPlayback({
    startSec,
    durationSec: Math.max(0.15, endSec - startSec),
    label: articulation,
    loop: false
  });
}

async function playMusicDeliverySection(sectionId, loop = false) {
  const section = findMusicDeliverySection(sectionId);
  if (!section) return;
  deliveryDashboardState.selectedSection = section.id;
  deliveryDashboardState.loopSection = !!loop;
  await startMusicDeliveryMixerPlayback({
    startSec: section.startSec,
    durationSec: section.durationSec,
    label: section.label,
    loop
  });
}

