function ensureDockPreviewEl() {
  if (dockDockPreviewEl) return dockDockPreviewEl;
  dockDockPreviewEl = document.createElement("div");
  dockDockPreviewEl.className = "dock-dock-preview";
  document.body.appendChild(dockDockPreviewEl);
  return dockDockPreviewEl;
}

function hideDockPreview() {
  if (!dockDockPreviewEl) return;
  dockDockPreviewEl.classList.remove("is-visible");
  delete dockDockPreviewEl.dataset.position;
}

function dockPreviewRect(position) {
  if (position === "left") return { left: 8, top: 24, width: 96, height: window.innerHeight - 48 };
  if (position === "right") return { left: window.innerWidth - 104, top: 24, width: 96, height: window.innerHeight - 48 };
  if (position === "top") return { left: Math.max(24, window.innerWidth / 2 - 320), top: 8, width: 640, height: 92 };
  return { left: Math.max(24, window.innerWidth / 2 - 320), top: window.innerHeight - 100, width: 640, height: 92 };
}

function resolveDockPositionFromPointer(clientX, clientY) {
  const edge = 108;
  const distances = [
    { position: "left", value: clientX },
    { position: "right", value: window.innerWidth - clientX },
    { position: "top", value: clientY },
    { position: "bottom", value: window.innerHeight - clientY }
  ].sort((a, b) => a.value - b.value);
  const nearest = distances[0];
  return nearest && nearest.value <= edge ? nearest.position : "";
}

function updateDockDragFollow(clientX, clientY) {
  if (!(dock instanceof HTMLElement)) return;
  dock.style.translate = "0 0";
}

function resetDockDragFollow() {
  if (!(dock instanceof HTMLElement)) return;
  dock.style.translate = "0 0";
}

function showDockPreview(position) {
  const preview = ensureDockPreviewEl();
  const rect = dockPreviewRect(position);
  preview.style.left = `${rect.left}px`;
  preview.style.top = `${rect.top}px`;
  preview.style.width = `${rect.width}px`;
  preview.style.height = `${rect.height}px`;
  preview.dataset.position = position;
  preview.classList.add("is-visible");
}

function attachDockDocking() {
  if (!(dock instanceof HTMLElement)) return;
  let dragging = false;
  let nextPosition = DOCK_POSITION;
  dock.addEventListener("pointerdown", (event) => {
    if (!DOCK_DOCKING_ENABLED) return;
    const target = event.target;
    if (!(target instanceof Element)) return;
    if (target.closest(".dock-item")) return;
    dragging = true;
    nextPosition = DOCK_POSITION;
    showDockPreview(nextPosition);
    dock.setPointerCapture?.(event.pointerId);
    event.preventDefault();
  });
  dock.addEventListener("pointermove", (event) => {
    if (!dragging || !DOCK_DOCKING_ENABLED) return;
    const resolved = resolveDockPositionFromPointer(event.clientX, event.clientY);
    updateDockDragFollow(event.clientX, event.clientY);
    if (!resolved) {
      hideDockPreview();
      nextPosition = DOCK_POSITION;
      dock.classList.remove("is-snapping");
      return;
    }
    nextPosition = resolved;
    showDockPreview(nextPosition);
    dock.classList.add("is-snapping");
  });
  const finish = (event) => {
    if (!dragging) return;
    dragging = false;
    hideDockPreview();
    resetDockDragFollow();
    dock.releasePointerCapture?.(event.pointerId);
    dock.classList.add("is-snapping");
    setTimeout(() => dock.classList.remove("is-snapping"), 520);
    updatePanelBehaviorSettings((current) => ({
      ...current,
      dock: { ...current.dock, dock_position: nextPosition }
    }));
  };
  dock.addEventListener("pointerup", finish);
  dock.addEventListener("pointercancel", (event) => {
    resetDockDragFollow();
    finish(event);
  });
}

function attachDockEvents() {
  if (!(dock instanceof HTMLElement)) return;
  if (dock.dataset.eventsBound === "true") return;
  dock.dataset.eventsBound = "true";
  document.addEventListener("pointerdown", (event) => {
    if (!dockSettingsPopover || dockSettingsPopover.hidden) return;
    const target = event.target;
    if (!(target instanceof Element)) return;
    if (target.closest(".dock-settings-popover")) return;
    if (target.closest('.dock-item[data-action="settings"]')) return;
    globalThis.hideDockSettingsPopoverModule?.();
  });
  window.addEventListener("resize", () => {
    globalThis.positionDockSettingsPopoverModule?.();
  });
  // P2-40: horizontal/vertical finger travel above this (px) is a swipe,
  // not a tap — suppress the click so Tesla/phone gestures don't accidentally
  // activate a dock item.
  const DOCK_SWIPE_THRESHOLD_PX = 14;
  dock.querySelectorAll(".dock-item").forEach((item) => {
    const action = item.dataset.action;
    item.tabIndex = 0;
    let suppressClick = false;
    let longPressId = 0;
    let lastPointerUpAt = 0;
    let pointerDownAt = 0;
    let pointerStartX = 0;
    let pointerStartY = 0;
    let pointerMaxDist = 0;
    let activePointerId = null;

    const triggerAction = (type) => {
      handleDockAction(action, type);
    };

    item.addEventListener("pointerdown", (event) => {
      if (Date.now() < dockSuppressUntil) return;
      suppressClick = false;
      pointerDownAt = Date.now();
      pointerStartX = event.clientX;
      pointerStartY = event.clientY;
      pointerMaxDist = 0;
      activePointerId = event.pointerId;
      clearTimeout(longPressId);
      if (action === "mic") {
        setLongpressGuard(false);
        return;
      }
      setLongpressGuard(true);
      longPressId = setTimeout(() => {
        suppressClick = true;
        triggerAction("longpress");
      }, LONGPRESS_MS);
    });

    item.addEventListener("pointermove", (event) => {
      if (activePointerId !== null && event.pointerId !== activePointerId) return;
      const dist = Math.hypot(
        event.clientX - pointerStartX,
        event.clientY - pointerStartY
      );
      if (dist > pointerMaxDist) pointerMaxDist = dist;
      if (dist >= DOCK_SWIPE_THRESHOLD_PX) {
        // The user is swiping, not tapping. Cancel the long-press timer and
        // flag this gesture so pointerup below won't fire a click.
        if (!suppressClick) {
          suppressClick = true;
          clearTimeout(longPressId);
          setLongpressGuard(false);
        }
      }
    });

    item.addEventListener("pointerup", () => {
      clearTimeout(longPressId);
      setLongpressGuard(false);
      activePointerId = null;
      if (Date.now() < dockSuppressUntil || item.classList.contains("is-dragging")) return;
      // P2-40: second safety check — if the finger travelled more than the
      // swipe threshold at any point during this pointer cycle, treat this as
      // a swipe and skip triggering an action.
      if (pointerMaxDist >= DOCK_SWIPE_THRESHOLD_PX) {
        suppressClick = true;
      }
      const heldLongEnough = action === "mic" && pointerDownAt && Date.now() - pointerDownAt >= LONGPRESS_MS;
      pointerDownAt = 0;
      if (suppressClick) {
        suppressClick = false;
        lastPointerUpAt = 0;
        clearTimeout(dockClickTimers.get(action));
        return;
      }
      if (heldLongEnough) {
        lastPointerUpAt = 0;
        clearTimeout(dockClickTimers.get(action));
        return;
      }
      const now = Date.now();
      clearTimeout(dockClickTimers.get(action));
      if (lastPointerUpAt && now - lastPointerUpAt <= CLICK_DELAY) {
        lastPointerUpAt = 0;
        triggerAction("dblclick");
        return;
      }
      lastPointerUpAt = now;
      const timer = setTimeout(() => {
        if (lastPointerUpAt !== now) return;
        lastPointerUpAt = 0;
        triggerAction("click");
      }, CLICK_DELAY);
      dockClickTimers.set(action, timer);
    });

    item.addEventListener("pointerleave", () => {
      clearTimeout(longPressId);
      setLongpressGuard(false);
      pointerDownAt = 0;
      // P2-40: leaving the item with an active press almost always means a
      // swipe/drag — suppress the click that the browser may still fire.
      if (activePointerId !== null) suppressClick = true;
      activePointerId = null;
    });

    item.addEventListener("pointercancel", () => {
      clearTimeout(longPressId);
      setLongpressGuard(false);
      pointerDownAt = 0;
      suppressClick = true;
      activePointerId = null;
    });

    item.addEventListener("click", (event) => {
      event.preventDefault();
      event.stopPropagation();
    });

    item.addEventListener("dblclick", (event) => {
      event.preventDefault();
      event.stopPropagation();
    });
  });
}

function attachGlobalActionDispatcher() {
  document.addEventListener("click", (event) => {
    const target = event.target;
    if (!(target instanceof Element)) return;
    if (target.closest(".dock-item")) return;
    const actionEl = target.closest("[data-action]");
    if (!actionEl) return;
    if (actionEl.getAttribute("data-hold") === "mic") return;
    const action = actionEl.getAttribute("data-action");
    handleGlobalAction(action);
  });
}

function attachPanelDrag() {
  document.querySelectorAll(".panel").forEach((panel) => {
    const handle =
      (panel === logoPanel ? panel.querySelector("[data-drag-handle]") : null) ||
      panel.querySelector(".panel-bar") ||
      panel.querySelector("[data-drag-handle]");
    if (!handle) return;
    let offsetX = 0;
    let offsetY = 0;
    let dragging = false;
    let pending = false;
    let pendingPointerId = null;
    let startX = 0;
    let startY = 0;

    handle.addEventListener("pointerdown", (event) => {
      if (event.target.closest(".panel-actions")) return;
      if (event.target.closest("button")) return;
      if (event.target.closest("[data-hold='mic']")) return;
      if (panel.classList.contains("panel-locked")) return;
      if (panel === logoPanel) {
        pending = true;
        pendingPointerId = event.pointerId;
        startX = event.clientX;
        startY = event.clientY;
        panel.dataset.logoGestureDragging = "false";
        forceResetHoldRing();
        setLongpressGuard(false);
        return;
      }
      panel.dataset.userMoved = "true";
      panel.classList.remove("showcase-panel");
      if (panel.dataset.maximized === "true") {
        restorePanel(panel);
      }
      dragging = true;
      panel.classList.add("dragging");
      focusPanel(panel);
      const rect = panel.getBoundingClientRect();
      offsetX = event.clientX - rect.left;
      offsetY = event.clientY - rect.top;
      handle.setPointerCapture(event.pointerId);
      event.preventDefault();
    });

    handle.addEventListener("pointermove", (event) => {
      if (panel === logoPanel && pending && !dragging) {
        if (pendingPointerId !== event.pointerId) return;
        const distance = Math.hypot(event.clientX - startX, event.clientY - startY);
        if (distance < 10) return;
        pending = false;
        panel.dataset.userMoved = "true";
        panel.classList.remove("showcase-panel");
        if (panel.dataset.maximized === "true") {
          restorePanel(panel);
        }
        dragging = true;
        panel.dataset.logoGestureDragging = "true";
        panel.classList.add("dragging");
        focusPanel(panel);
        const rect = panel.getBoundingClientRect();
        offsetX = startX - rect.left;
        offsetY = startY - rect.top;
        handle.setPointerCapture(event.pointerId);
        event.preventDefault();
      }
      if (!dragging) return;
      spawnDragTrail(event);
      const proposedLeft = event.clientX - offsetX;
      const proposedTop = event.clientY - offsetY;
      setPanelPosition(panel, proposedLeft, proposedTop);
    });

    const stopDrag = (event) => {
      if (panel === logoPanel && !dragging) {
        pending = false;
        pendingPointerId = null;
        panel.dataset.logoGestureDragging = "false";
        return;
      }
      dragging = false;
      pending = false;
      pendingPointerId = null;
      panel.dataset.logoGestureDragging = "false";
      panel.classList.remove("dragging");
      handle.releasePointerCapture?.(event.pointerId);
      persistPanelLayout(panel);
    };

    handle.addEventListener("pointerup", stopDrag);
    handle.addEventListener("pointercancel", stopDrag);
  });
}

function attachPanelBarActions() {
  document.querySelectorAll(".panel").forEach((panel) => {
    panel.addEventListener("dblclick", (event) => {
      if (event.target.closest(".panel-actions")) return;
      if (event.target.closest(".panel-settings")) return;
      if (
        event.target.closest("button") ||
        event.target.closest("input") ||
        event.target.closest("select") ||
        event.target.closest("textarea")
      ) {
        return;
      }
      togglePanelSettings(panel);
    });
  });
}

